import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type AiPromptAnimationProps = Record<string, any>;

const AiPromptAnimation: React.FC<AiPromptAnimationProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 12,
  primaryColor = "#8b5cf6",
  promptText = "How do I build a scalable animation system?",
  responseText = "To build a scalable animation system, prioritize pure functional state, separate logic from presentation, and establish a robust timeline architecture. Ensure every visual change is deterministically driven by the current frame.",
  containerWidthRatio = 0.65,
  themeMode = "dark",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Theme derived colors
  const isDark = themeMode === "dark";
  const textColor = isDark ? "#f8fafc" : "#0f172a";
  const inputBg = isDark ? "rgba(255, 255, 255, 0.05)" : "rgba(0, 0, 0, 0.05)";
  const inputBorder = isDark ? "rgba(255, 255, 255, 0.1)" : "rgba(0, 0, 0, 0.1)";
  const aiTextColor = isDark ? "#cbd5e1" : "#334155";

  // TIMELINE DEFINITIONS
  const INTRO_START = 0;
  const TYPING_START = 30;
  const TYPING_END = 90;
  const SUBMIT_START = 105;
  const THINKING_START = 120;
  const THINKING_END = 190;
  const RESPONSE_START = 190;

  // 1. Intro Animation
  const containerY = interpolate(frame, [INTRO_START, INTRO_START + 30], [50, 0], {
    easing: Easing.out(Easing.exp),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const containerOpacity = interpolate(frame, [INTRO_START, INTRO_START + 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 2. Prompt Typing Animation
  const promptChars = interpolate(frame, [TYPING_START, TYPING_END], [0, promptText.length], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const displayedPrompt = promptText.substring(0, Math.floor(promptChars));
  
  const isTyping = frame >= TYPING_START && frame < TYPING_END;
  const cursorBlink = isTyping ? 1 : Math.floor(frame / 15) % 2 === 0 ? 1 : 0;
  
  // 3. Submit Button Click
  const buttonScale = interpolate(
    frame,
    [SUBMIT_START, SUBMIT_START + 3, SUBMIT_START + 8],
    [1, 0.85, 1],
    {
      easing: Easing.out(Easing.quad),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  
  const submitGlow = interpolate(frame, [SUBMIT_START, SUBMIT_START + 5, SUBMIT_START + 15], [0, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 4. Thinking State (Loader)
  const loaderOpacity = interpolate(
    frame,
    [THINKING_START, THINKING_START + 10, THINKING_END - 10, THINKING_END],
    [0, 1, 1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  
  const loaderWidth = interpolate(frame, [THINKING_START, THINKING_END], [0, 100], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const thinkingPulse = 0.5 + Math.sin(frame * 0.15) * 0.5;

  // 5. Response Text Animation
  const words = responseText.split(" ");
  
  // Layout measurements
  const containerWidth = width * containerWidthRatio;
  
  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        <div
          style={{
            width: containerWidth,
            transform: `translateY(${containerY}px)`,
            opacity: containerOpacity,
            display: "flex",
            flexDirection: "column",
            gap: "40px",
            transition: "none",
          }}
        >
          {/* Input Box */}
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
              padding: "20px 24px",
              borderRadius: "24px",
              backgroundColor: inputBg,
              border: `1px solid ${inputBorder}`,
              boxShadow: submitGlow > 0 ? `0 0 ${submitGlow * 30}px ${primaryColor}40` : "none",
              position: "relative",
              overflow: "hidden",
            }}
          >
            {/* Input Text */}
            <div
              style={{
                flex: 1,
                fontSize: "32px",
                color: textColor,
                display: "flex",
                alignItems: "center",
                lineHeight: 1.2,
                minHeight: "40px",
              }}
            >
              <span>{displayedPrompt}</span>
              <span
                style={{
                  width: "4px",
                  height: "36px",
                  backgroundColor: primaryColor,
                  marginLeft: "4px",
                  opacity: cursorBlink,
                  borderRadius: "2px",
                }}
              />
            </div>

            {/* Submit Button */}
            <div
              style={{
                width: "48px",
                height: "48px",
                borderRadius: "16px",
                backgroundColor: frame >= SUBMIT_START ? primaryColor : inputBorder,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                transform: `scale(${buttonScale})`,
                transition: "none",
                marginLeft: "24px",
              }}
            >
              <svg
                width="24"
                height="24"
                viewBox="0 0 24 24"
                fill="none"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path
                  d="M12 4V20M12 4L6 10M12 4L18 10"
                  stroke={isDark ? "#ffffff" : "#000000"}
                  strokeWidth="2.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </div>

            {/* Loader Bar under input */}
            <div
              style={{
                position: "absolute",
                bottom: 0,
                left: 0,
                height: "2px",
                width: `${loaderWidth}%`,
                backgroundColor: primaryColor,
                opacity: loaderOpacity * thinkingPulse,
                transition: "none",
                boxShadow: `0 0 10px ${primaryColor}`,
              }}
            />
          </div>

          {/* Response Area */}
          <div
            style={{
              padding: "0 24px",
              fontFamily: spaceGroteskFamily,
              fontSize: "36px",
              lineHeight: 1.5,
              color: aiTextColor,
              minHeight: "200px",
              display: "flex",
              flexWrap: "wrap",
              alignContent: "flex-start",
            }}
          >
            {words.map((word, i) => {
              const wordStart = RESPONSE_START + i * 2;
              
              const wordOpacity = interpolate(
                frame,
                [wordStart, wordStart + 10],
                [0, 1],
                {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                }
              );
              
              const wordY = interpolate(
                frame,
                [wordStart, wordStart + 10],
                [15, 0],
                {
                  easing: Easing.out(Easing.quad),
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                }
              );

              return (
                <span
                  key={i}
                  style={{
                    opacity: wordOpacity,
                    transform: `translateY(${wordY}px)`,
                    display: "inline-block",
                    marginRight: "12px",
                    marginBottom: "12px",
                    transition: "none",
                  }}
                >
                  {word}
                </span>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default AiPromptAnimation;